                if c.is_alphanumeric() {
                    cur = cur + c.to_ascii_lowercase().to_string()
                } else {
                    if cur.len() > 0 {
                        counts.entry(cur).and_modify(|n| *n += 1).or_insert(1)
                    }
                    cur = ""
                }
            }
            if cur.len() > 0 {
                counts.entry(cur).and_modify(|n| *n += 1).or_insert(1)
            }
        }
    }
    let mut items: Vec<(string, int)> = []
    for (w, n) in counts {
        items.push((w, n))
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(a.1)
        } else {
            a.0.cmp(b.0)
        }
